use vstd::prelude::*;

verus! {

/// Concatenate two vectors of `u64` into a new `Vec<u64>`,
/// preserving the order of elements.
fn concat(a: &Vec<u64>, b: &Vec<u64>) -> Vec<u64>
    ensures
        // The resulting sequence has length equal to the sum of the inputs
        result@.len() == a@.len() + b@.len(),
        // The first part of `result` matches all of `a`
        forall i: nat :: i < a@.len() ==>
            result@.index(i) == a@.index(i),
        // The second part of `result` matches all of `b`
        forall j: nat :: j < b@.len() ==>
            result@.index(a@.len() + j) == b@.index(j),
{
    // Pre‐allocate enough space for both vectors
    let mut result = Vec::with_capacity(a.len() + b.len());

    // Copy all elements from the first vector
    result.extend_from_slice(a);

    // Copy all elements from the second vector
    result.extend_from_slice(b);

    result
}

} // verus!

